using System;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using LWS.TruckSports.Editor;
namespace LWS.TruckTerrierRacing.Editor {
 public static class TerrierGoddessAuthoring {
  [MenuItem("Truck Sports/Terrier/Upgrade final funnel, basalt and cherry (preserve scene)")]
  public static void Upgrade(){EditorSceneManager.OpenScene(TerrierAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<TerrierMatch>();Install(m);EditorSceneManager.SaveScene(m.gameObject.scene);AssetDatabase.SaveAssets();}
  public static void Install(TerrierMatch m){var c=m.course;if(c.sideRails.Length!=6){var old=c.sideRails;var next=new Transform[6];for(int side=0;side<2;side++){next[side*3]=old[side*2];next[side*3+1]=old[side*2+1];next[side*3+2]=UnityEngine.Object.Instantiate(old[side*2+1],old[side*2+1].parent);next[side*3+2].name="Final funnel side board "+side;}c.sideRails=next;}c.UpdateGeometry();EditorUtility.SetDirty(c.groundMesh.sharedMesh);EditorUtility.SetDirty(c);
   var layer=AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Rock Base/Rock_Base_VistaSample.terrainlayer");if(layer==null||layer.diffuseTexture==null)throw new Exception("Installed Vista basalt surface required");var mat=SportsEventAuthoring.Mat(TerrierAuthoring.Folder,"Weathered volcanic racing basalt",new Color(.54f,.49f,.45f),.13f);mat.SetTexture("_BaseMap",layer.diffuseTexture);mat.SetTexture("_BumpMap",layer.normalMapTexture);mat.SetFloat("_BumpScale",.7f);mat.EnableKeyword("_NORMALMAP");c.groundMesh.GetComponent<MeshRenderer>().sharedMaterial=mat;EditorUtility.SetDirty(mat);
   foreach(var patch in c.patches){var r=patch.GetComponent<Renderer>();if(r!=null)r.sharedMaterial=mat;}RemoveStairs(m);Cherry(m);InstallDessertLabel(m);Grade(m);EditorUtility.SetDirty(m);
  }
  static void Grade(TerrierMatch m){var cameras=new Camera[m.cabViews.Length+1];cameras[0]=m.broadcast.view;for(int i=0;i<m.cabViews.Length;i++)cameras[i+1]=m.cabViews[i].view;var catalog=SportsWeatherPresetsAuthoring.EnsureCatalog();m.course.weather.presets=catalog;SportsWeatherRenderingAuthoring.Install(m.gameObject,cameras,TerrierAuthoring.Folder);SportsWeatherPickerAuthoring.Install(m,catalog,new Vector2(0,336));var title=m.menus.pages[0].transform.Find("Title").GetComponent<RectTransform>();title.anchoredPosition=new Vector2(0,430);foreach(var label in m.menus.pages[0].GetComponentsInChildren<TMPro.TMP_Text>(true))if(label.name=="Weather selection explanation")label.gameObject.SetActive(false);EditorUtility.SetDirty(m.course.weather);var pipeline=(UnityEngine.Rendering.Universal.UniversalRenderPipelineAsset)m.GetComponent<LWS.TruckBaseJumping.BaseJumpRendering>().pipeline;var state=new SerializedObject(pipeline);var list=state.FindProperty("m_RendererDataList");const string path="Assets/TruckTerrierRacing/Rendering/Terrier native post renderer.asset";var renderer=AssetDatabase.LoadAssetAtPath<UnityEngine.Rendering.Universal.UniversalRendererData>(path);if(renderer==null){var source=(UnityEngine.Rendering.Universal.UniversalRendererData)list.GetArrayElementAtIndex(0).objectReferenceValue;renderer=UnityEngine.Object.Instantiate(source);renderer.name="Terrier native weather and post renderer";if(renderer.postProcessData==null){var reference=AssetDatabase.LoadAssetAtPath<UnityEngine.Rendering.Universal.UniversalRendererData>("Assets/TruckDanceOff/Rendering/Concert renderer.asset");if(reference==null||reference.postProcessData==null)throw new Exception("Existing native URP post process resources required");var data=new SerializedObject(renderer);data.FindProperty("m_PostProcessData").objectReferenceValue=reference.postProcessData;data.ApplyModifiedPropertiesWithoutUndo();}AssetDatabase.CreateAsset(renderer,path);}list.GetArrayElementAtIndex(0).objectReferenceValue=renderer;state.ApplyModifiedPropertiesWithoutUndo();pipeline.supportsHDR=true;EditorUtility.SetDirty(pipeline);SportsScenicGradeAuthoring.Install(m.gameObject,cameras,TerrierAuthoring.Folder,-.8f);Debug.Log("TERRIER_NATIVE_GRADE rendererPost="+(renderer.postProcessData!=null)+" cameras="+cameras.Length);}
  public static void RemoveStairs(TerrierMatch m){if(m.volcano==null)return;var stairs=m.volcano.transform.Find("Installed scaffold bridge pylons");if(stairs!=null)UnityEngine.Object.DestroyImmediate(stairs.gameObject);}
  public static void InstallDessertLabel(TerrierMatch m){if(m.dessert==null)return;var root=m.dessert.basin;var old=root.Find("Dessert basin lettering");if(old!=null){old.GetComponent<Renderer>().enabled=false;EditorUtility.SetDirty(old.GetComponent<Renderer>());}var label=root.Find("Depth-tested dessert lettering");var text=label!=null?label.GetComponent<TMPro.TextMeshPro>():new GameObject("Depth-tested dessert lettering").AddComponent<TMPro.TextMeshPro>();text.transform.SetParent(root,false);text.transform.localPosition=new Vector3(0,TerrierDessert.Profile(0,-120)+.22f,-120);text.transform.localRotation=Quaternion.Euler(90,0,0);var font=Resources.Load<LWS.TruckSports.SportsBroadcastTheme>("SportsBroadcastTheme").headingFont;text.font=font;text.text="I SCREAM!";text.fontSize=60;text.enableAutoSizing=false;text.alignment=TMPro.TextAlignmentOptions.Center;text.color=new Color(.36f,.035f,.10f);text.rectTransform.sizeDelta=new Vector2(150,18);text.isOverlay=false;const string path="Assets/TruckTerrierRacing/Art/IceCream/Depth-tested dessert lettering.mat";var material=AssetDatabase.LoadAssetAtPath<Material>(path);if(material==null){material=new Material(font.material);material.name="Depth-tested dessert lettering";material.shader=Shader.Find("TextMeshPro/Distance Field");AssetDatabase.CreateAsset(material,path);}text.fontSharedMaterial=material;text.ForceMeshUpdate();EditorUtility.SetDirty(material);EditorUtility.SetDirty(text);}
  public static void Cherry(TerrierMatch m){if(m.dessert==null||m.dessert.basin.Find("Gigantic maraschino cherry")!=null)return;var root=new GameObject("Gigantic maraschino cherry").transform;root.SetParent(m.dessert.basin,false);root.localPosition=new Vector3(42,TerrierDessert.Profile(42,68)+6.4f,68);
   var red=SportsEventAuthoring.Mat(TerrierAuthoring.Folder,"Glossy maraschino red",new Color(.65f,.008f,.025f),.84f);var stem=SportsEventAuthoring.Mat(TerrierAuthoring.Folder,"Cherry stem green",new Color(.13f,.23f,.025f),.4f);var mesh=new Mesh{name="Original dimpled cherry skin"};const int rings=32,segments=48;var v=new List<Vector3>();var uv=new List<Vector2>();var tri=new List<int>();for(int r=0;r<=rings;r++){float a=r*Mathf.PI/rings;for(int j=0;j<=segments;j++){float b=j*Mathf.PI*2/segments;float radius=8*(1+.035f*Mathf.Cos(b*3)*Mathf.Sin(a));float y=Mathf.Cos(a)*8-1.5f*Mathf.Exp(-a*a*7);v.Add(new Vector3(Mathf.Sin(a)*Mathf.Cos(b)*radius,y,Mathf.Sin(a)*Mathf.Sin(b)*radius));uv.Add(new Vector2(j/(float)segments,r/(float)rings));}}for(int r=0;r<rings;r++)for(int j=0;j<segments;j++){int a=r*(segments+1)+j,b=a+segments+1;tri.AddRange(new[]{a,a+1,b,b,a+1,b+1});}mesh.SetVertices(v);mesh.SetUVs(0,uv);mesh.SetTriangles(tri,0);mesh.RecalculateNormals();mesh.RecalculateBounds();const string path="Assets/TruckTerrierRacing/Art/IceCream/Original dimpled cherry.asset";var saved=AssetDatabase.LoadAssetAtPath<Mesh>(path);if(saved==null){AssetDatabase.CreateAsset(mesh,path);saved=mesh;}else UnityEngine.Object.DestroyImmediate(mesh);root.gameObject.AddComponent<MeshFilter>().sharedMesh=saved;root.gameObject.AddComponent<MeshRenderer>().sharedMaterial=red;
   var line=new GameObject("Curved cherry stem").AddComponent<LineRenderer>();line.transform.SetParent(root,false);line.useWorldSpace=false;line.positionCount=25;line.widthMultiplier=.55f;line.numCapVertices=6;line.numCornerVertices=4;line.sharedMaterial=stem;for(int i=0;i<25;i++){float t=i/24f;line.SetPosition(i,new Vector3(5*t*t,6.3f+12*t,2*Mathf.Sin(t*Mathf.PI)));} // Decorative, collision-free and away from the winner's landing line.
   EditorUtility.SetDirty(m.dessert);
  }
 }
